INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 11, 'theory', 'Quiz: the ALU');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 0, 'How does the ALU switch between operations?', '["Only the needed block is turned on", "Operations are executed one after another", "The operation code is fed to the adder", "All operations are computed in parallel, and a multiplexer selects the result by the operation code"]', 3, 'The gates work simultaneously, so the "extra" computations cost nothing in time. The choice is made by the multiplexer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 1, 'How does the ALU compute A − B?', '["With a separate subtraction block", "As A + not B + 1: it inverts B and feeds a carry of one", "By shifting B to the right", "By comparing bits"]', 1, 'Subtraction is reduced to addition in two''s complement. That is why no separate subtraction circuit is needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 2, 'What does the Z flag mean?', '["The result is zero", "The result is negative", "There was an overflow", "There was a subtraction"]', 0, 'Z (zero) is one when all bits of the result are zeros. It is used in the "equal" and "not equal" conditions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 3, 'Why do we need the V flag if there is already the carry C?', '["They are always equal", "V is needed only for subtraction", "C shows out of range for unsigned numbers, and V for signed numbers", "V is the same as Z"]', 2, '7 + 1 in four signed bits gives 1000 (−8): there is no carry, but the result is wrong, and that is overflow. 15 + 1 gives a carry, but for unsigned numbers that is exactly out of range.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 11, 4, 'How does a processor compare two numbers?', '["Checks each pair of bits for equality", "Subtracts and looks at the flags; the result itself is not saved", "Adds the numbers and compares with zero", "Uses a multiplexer"]', 1, 'Equality is Z = 1, "less" is determined by the carry (unsigned) or by N xor V (signed). From the flags the signal T is built: the branch condition.');
